@extends('layouts.app') @section('content')<div class="container-fluid my-4"><h2>Evaluaciones de capacitación</h2>@include('training.partials.nav')@php($sessions=\App\Models\TrainingSession::forCompany(auth()->user()->company_id)->whereIn('status',['completed','closed'])->with('topic')->get())@php($topics=\App\Models\TrainingTopic::availableTo(auth()->user()->company_id)->where('is_active',true)->get())<form method="POST" action="{{route('training.evaluations.store')}}" class="card card-body mb-3">@csrf<div class="form-row"><div class="col"><select name="training_session_id" class="form-control" required>@foreach($sessions as $session)<option value="{{$session->id}}">{{$session->title}} — {{$session->scheduled_start_at->format('d/m/Y')}}</option>@endforeach</select></div><div class="col"><select name="training_topic_id" class="form-control" required><option value="">Tema del banco de preguntas…</option>@foreach($topics as $topic)<option value="{{$topic->id}}">{{$topic->name}}</option>@endforeach</select></div><div class="col"><input name="title" class="form-control" placeholder="Título" required></div><div class="col"><select name="evaluation_type" class="form-control"><option value="knowledge_quiz">Cuestionario de conocimientos</option><option value="practical_checklist">Lista de chequeo práctica</option><option value="instructor_assessment">Evaluación del instructor</option><option value="mixed">Mixta</option><option value="external">Externa</option></select></div></div><textarea name="instructions" class="form-control my-2" placeholder="Instrucciones" required></textarea><div class="form-row"><div class="col"><select name="evaluation_phase" class="form-control"><option value="post_test">Evaluación posterior</option><option value="pre_test">Evaluación previa</option></select></div><div class="col"><input type="number" step="0.01" name="passing_score" class="form-control" placeholder="Puntaje mínimo %" required></div><div class="col"><input type="number" name="maxi